using System;
using System.Collections.Immutable;
using System.Linq;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Projects")]
    [TestClass]
    public class RJIT_CR_CSPROJ_00002 : ControllerTestBase
    {
        [DataTestMethod]
        [DataRow("LangVersion", "latestmajor")]
        [DataRow("EnableNETAnalyzers", "true")]
        [DataRow("AnalysisLevel", "latest")]
        [DataRow("Nullable", "enable")]
        [DataRow("EnforceCodeStyleInBuild", "true")]
        [DataRow("WarningsAsErrors", "Nullable")]
        [DataRow("TreatWarningsAsErrors", "true")]
        public void Mandatory_Project_Settings_Have_To_Be_Set(string elementName, string expectedValue)
        {
            var directoryBuildPropsExist = Solution.SolutionFileInfo.Value.Directory.EnumerateFiles("Directory.Build.props").FirstOrDefault().IsNotNull();
            
            var invalidSettings = (from project in Solution.Projects
                                            let element = project.Document.ElementBy(elementName)
                                            where element is not null &&
                                                  element.Value.NotEqualsTo(expectedValue) &&
                                                  directoryBuildPropsExist.IsFalse() // It can be that directory.build.props is not existent already exist with all those settings
                                            select new
                                            {
                                                Project = project.ProjectFileInfo.FileNameWithoutExtenion,
                                                Element = elementName,
                                                ExpectedValue = expectedValue,
                                                CurrentValue = element.Value
                                            }).ToImmutableList();

            Assert.IsTrue(invalidSettings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00001

Your project settings are not correctly setup. Please update your csproj or even better setup your 
'Directory.Build.props' to have a centralized place to setup all csproj settings in one centralized
file.{Environment.NewLine}Found: '{invalidSettings.Count}'{Environment.NewLine}{Environment.NewLine}{ConsoleTable.From(invalidSettings)}{Environment.NewLine}");
        }
    }
